def calculate_telemedicine_cost(base_fee, minutes_used, cost_per_minute):
    if minutes_used <= 0:
        return 0
    return base_fee + (minutes_used * cost_per_minute)

def recursive_sum(nums):
    """Return the sum of a list of integers using recursion."""
    if not nums:  # Base case: empty list
        return 0
    return nums[0] + recursive_sum(nums[1:])


def main():
    # Sample list to test the function
    numbers = [4, 7, 2, 9, 1]
    total = recursive_sum(numbers)
    print("The sum of the list is:", total)


if __name__ == "__main__":
    main()

