import os


def get_app_mode_message():
    """Return a message based on the APP_MODE environment variable."""
    app_mode = os.getenv('APP_MODE')

    if app_mode == 'development':
        return 'Running in development mode'
    elif app_mode == 'production':
        return 'Running in production mode'
    else:
        return 'Running in default mode'


